(45461, 'Psalms 118:10', 'Psalms', 118, 10, 'رانه چاپېر وو ټول قومونه خو د څښتن په زور مې دوی کړل تباه', 'رانه چاپېر وو تول قومونه خو د چشتن په زور مې دوی کرل تباه', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Psalms_118_10.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237843, 1761237843),
(45462, 'Psalms 118:11', 'Psalms', 118, 11, 'وو راچاپېر هغوی د هرې خوا نه په ما خو د څښتن په زور مې دوی کړل تباه', 'وو راچاپېر هغوی د هرې خوا نه په ما خو د چشتن په زور مې دوی کرل تباه', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Psalms_118_11.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237843, 1761237843),
(45463, 'Psalms 118:12', 'Psalms', 118, 12, 'رانه چاپېر وو هغوی لکه مچیو په شان خو هغوی خاموش شول لکه د اغزیو د اور په شان د څښتن په زور مې دوی کړل تباه', 'رانه چاپېر وو هغوی لکه مچیو په شان خو هغوی خاموش شول لکه د اغزیو د اور په شان د چشتن په زور مې دوی کرل تباه', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Psalms_118_12.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237843, 1761237843),
(45464, 'Psalms 118:13', 'Psalms', 118, 13, 'سخته حمله راباندې وشوه او نژدې ؤ چې زه ماتې وخورم خو څښتن وکړلو کومک راسره', 'سخته حمله راباندې وشوه او نژدې و چې زه ماتې وخورم خو چشتن وکرلو کومک راسره', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Psalms_118_13.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237843, 1761237843),
(45465, 'Psalms 118:14', 'Psalms', 118, 14, 'څښتن زما قوت دی او دفاع یې زما وکړه او زه یې ژغورلی یمه', 'چشتن زما قوت دی او دفاع یې زما وکره او زه یې ژغورلی یمه', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Psalms_118_14.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237843, 1761237843),
(45466, 'Psalms 118:15', 'Psalms', 118, 15, 'د خدای د قوم د خېمو نه واورئ د کامیابۍ په خاطر د خوشحالۍ چیغې چې د څښتن په قوي لاس دا هرڅه شوي دي', 'د خدای د قوم د خېمو نه واوری د کامیابی په خاطر د خوشحالی چیغې چې د چشتن په قوی لاس دا هرچه شوی دی', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Psalms_118_15.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237843, 1761237843),
(45467, 'Psalms 118:16', 'Psalms', 118, 16, 'مونږ بریالي شو د څښتن په قوي لاس باندې په جګړه کې د هغه په زورور قوت', 'مونز بریالی شو د چشتن په قوی لاس باندې په جګره کې د هغه په زورور قوت', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Psalms_118_16.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237843, 1761237843),
(45468, 'Psalms 118:17', 'Psalms', 118, 17, 'زه به مړ نه شم بلکې ژوندی به یمه زه به بیان کړم کوم کارونه چې څښتن کړي دي', 'زه به مر نه شم بلکې ژوندی به یمه زه به بیان کرم کوم کارونه چې چشتن کری دی', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Psalms_118_17.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237843, 1761237843),
(45469, 'Psalms 118:18', 'Psalms', 118, 18, 'هغه راکړې راته سخته سزا خو زه یې پرېنښودم چې مړ شمه', 'هغه راکرې راته سخته سزا خو زه یې پرېنشودم چې مر شمه', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Psalms_118_18.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237843, 1761237843),
(45470, 'Psalms 118:19', 'Psalms', 118, 19, 'ماته کړئ خلاصې دروازې د معبد چې زه ورشم د څښتن شکر ادا کړم په کې', 'ماته کری خلاصې دروازې د معبد چې زه ورشم د چشتن شکر ادا کرم په کې', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Psalms_118_19.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237843, 1761237843),
(45471, 'Psalms 118:20', 'Psalms', 118, 20, 'دا هغه دروازه ده چې کولای شئ څښتن ته ورشئ یوازې نېک خلک کولای شي داخل شي په کې', 'دا هغه دروازه ده چې کولای شی چشتن ته ورشی یوازې نېک خلک کولای شی داخل شی په کې', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Psalms_118_20.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237843, 1761237843),
(45472, 'Psalms 118:21', 'Psalms', 118, 21, 'شکر کومه زه د ستا څښتنه ځکه چې سوال دې قبول کړی زما ځکه چې ماته دی نجات راکړی', 'شکر کومه زه د ستا چشتنه جکه چې سوال دې قبول کری زما جکه چې ماته دی نجات راکری', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Psalms_118_21.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237843, 1761237843),
(45473, 'Psalms 118:22', 'Psalms', 118, 22, 'کومه تیږه چې رد کړې ګلکارانو وه هغه اوس شوه اصلي تیږه د تهداب', 'کومه تیزه چې رد کرې ګلکارانو وه هغه اوس شوه اصلی تیزه د تهداب', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Psalms_118_22.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237843, 1761237843),
(45474, 'Psalms 118:23', 'Psalms', 118, 23, 'دا کار وشو د څښتن له خوا نه او عجیبه ښکاري زمونږ نظر کې', 'دا کار وشو د چشتن له خوا نه او عجیبه شکاری زمونز نظر کې', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Psalms_118_23.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237843, 1761237843),
(45475, 'Psalms 118:24', 'Psalms', 118, 24, 'دا هغه ورځ ده چې څښتن په کې کړی دی عجیبه کار راځئ چې وکړو خوشحالي او په کې خوشحاله اوسو', 'دا هغه ورج ده چې چشتن په کې کری دی عجیبه کار راجی چې وکرو خوشحالی او په کې خوشحاله اوسو', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Psalms_118_24.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237843, 1761237843),
(45476, 'Psalms 118:25', 'Psalms', 118, 25, 'مونږه وژغوره څښتنه، مونږه وژغوره ای څښتنه بری راکړه مونږ ته', 'مونزه وژغوره چشتنه، مونزه وژغوره ای چشتنه بری راکره مونز ته', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Psalms_118_25.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237843, 1761237843),
(45477, 'Psalms 118:26', 'Psalms', 118, 26, 'مبارک دی هغه څوک چې د څښتن په نوم راځي تاسو ته غواړو برکت مونږ د څښتن له کوره', 'مبارک دی هغه چوک چې د چشتن په نوم راجی تاسو ته غوارو برکت مونز د چشتن له کوره', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Psalms_118_26.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237843, 1761237843),
(45478, 'Psalms 118:27', 'Psalms', 118, 27, 'څښتن دی خدای چې یې وځلوله خپله رڼا په مونږ د قربانۍ حیوان راولئ او د قربانګاه په کنجونو باندې یې وتړئ رسیو باندې', 'چشتن دی خدای چې یې وجلوله خپله رنا په مونز د قربانی حیوان راولی او د قربانګاه په کنجونو باندې یې وتری رسیو باندې', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Psalms_118_27.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237843, 1761237843),
(45479, 'Psalms 118:28', 'Psalms', 118, 28, 'ته زما خدای یې او ستا شکر کوم ته مې خدای یې، زه به ستا لویي بیان کړم', 'ته زما خدای یې او ستا شکر کوم ته مې خدای یې، زه به ستا لویی بیان کرم', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Psalms_118_28.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237843, 1761237843),
(45480, 'Psalms 118:29', 'Psalms', 118, 29, 'د څښتن شکر کوئ، ځکه چې نېک دی هغه ده ابدي د هغه مینه', 'د چشتن شکر کوی، جکه چې نېک دی هغه ده ابدی د هغه مینه', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Psalms_118_29.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237843, 1761237843),
