(45536, 'Deuteronomy 10:7', 'Deuteronomy', 10, 7, 'هغوی د هغه ځای څخه جدجوده ته او بیا یطبات ته سفر وکړ، یعنې هغې خاورې ته چې د اوبو ویالې په کې وې.', 'هغوی د هغه جای چخه جدجوده ته او بیا یطبات ته سفر وکر، یعنې هغې خاورې ته چې د اوبو ویالې په کې وې.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Deuteronomy_10_7.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237843, 1761237843),
(45537, 'Deuteronomy 10:8', 'Deuteronomy', 10, 8, 'په هغه وخت کې څښتن د لاوي قبیله غوره کړله چې د لوظ صندوق یوسي، د کاهنانو په توګه د څښتن خدمت وکړي او د هغه په نوم برکت ورکړي. تر اوسه پورې دا د هغوی دندې دي.', 'په هغه وخت کې چشتن د لاوی قبیله غوره کرله چې د لوظ صندوق یوسی، د کاهنانو په توګه د چشتن خدمت وکری او د هغه په نوم برکت ورکری. تر اوسه پورې دا د هغوی دندې دی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Deuteronomy_10_8.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237843, 1761237843),
(45538, 'Deuteronomy 10:9', 'Deuteronomy', 10, 9, 'نو ځکه د لاوي قبیلې د نورو قبیلو په شان ځمکه تر لاسه نه کړه. ستاسو د څښتن خدای د وعدې سره سم څه چې هغوی تر لاسه کړل هغه د څښتن د کاهنتوب امتیاز ؤ.', 'نو جکه د لاوی قبیلې د نورو قبیلو په شان جمکه تر لاسه نه کره. ستاسو د چشتن خدای د وعدې سره سم چه چې هغوی تر لاسه کرل هغه د چشتن د کاهنتوب امتیاز و.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Deuteronomy_10_9.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237843, 1761237843),
(45539, 'Deuteronomy 10:10', 'Deuteronomy', 10, 10, 'زه د لومړي ځل په شان څلوېښت شپې او ورځې په غره کې پاتې شوم. څښتن یوځل بیا زما دعا قبوله کړه او په دې راضي شو چې تاسو تباه نه کړي.', 'زه د لومری جل په شان چلوېشت شپې او ورجې په غره کې پاتې شوم. چشتن یوجل بیا زما دعا قبوله کره او په دې راضی شو چې تاسو تباه نه کری.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Deuteronomy_10_10.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237843, 1761237843),
(45540, 'Deuteronomy 10:11', 'Deuteronomy', 10, 11, 'بیا هغه ماته وویل چې لاړ شم او ستاسو مشري وکړم، ترڅو تاسو وکولای شئ هغه ځمکه تر لاسه کړئ چې هغه وعده کړې وه چې ستاسو نیکونو ته به یې ورکړي.', 'بیا هغه ماته وویل چې لار شم او ستاسو مشری وکرم، ترچو تاسو وکولای شی هغه جمکه تر لاسه کری چې هغه وعده کرې وه چې ستاسو نیکونو ته به یې ورکری.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Deuteronomy_10_11.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237843, 1761237843),
(45541, 'Deuteronomy 10:12', 'Deuteronomy', 10, 12, 'د اسراییلو خلکو، ستاسو څخه خپل څښتن خدای څه غواړي؟ د هغه څخه ووېرېږئ او ټول امرونه یې په ځای کوئ. د هغه سره مینه کوئ او د زړه له کومي یې خدمت کوئ', 'د اسراییلو خلکو، ستاسو چخه خپل چشتن خدای چه غواری؟ د هغه چخه ووېرېزی او تول امرونه یې په جای کوی. د هغه سره مینه کوی او د زره له کومی یې خدمت کوی', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Deuteronomy_10_12.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237843, 1761237843),
(45542, 'Deuteronomy 10:13', 'Deuteronomy', 10, 13, 'او د هغه د ټولو قوانینو اطاعت کوئ. زه نن دا قوانین تاسو ته ستاسو د ګټې په خاطر درکوم.', 'او د هغه د تولو قوانینو اطاعت کوی. زه نن دا قوانین تاسو ته ستاسو د ګتې په خاطر درکوم.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Deuteronomy_10_13.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237843, 1761237843),
(45543, 'Deuteronomy 10:14', 'Deuteronomy', 10, 14, 'ټول اسمانونه ستاسو د څښتن خدای دي. ځمکه او هرڅه چې په کې دي هغه هم د څښتن دي.', 'تول اسمانونه ستاسو د چشتن خدای دی. جمکه او هرچه چې په کې دی هغه هم د چشتن دی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Deuteronomy_10_14.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237843, 1761237843),
(45544, 'Deuteronomy 10:15', 'Deuteronomy', 10, 15, 'خو څښتن ستاسو د نیکونو سره دومره زیاته مینه کوله چې تاسو یې د ځمکې په مخ د ټولو قومونو څخه غوره کړئ او تر نن ورځې پورې د هغه غوره شوی قوم یئ.', 'خو چشتن ستاسو د نیکونو سره دومره زیاته مینه کوله چې تاسو یې د جمکې په مخ د تولو قومونو چخه غوره کری او تر نن ورجې پورې د هغه غوره شوی قوم یی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Deuteronomy_10_15.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237843, 1761237843),
(45545, 'Deuteronomy 10:16', 'Deuteronomy', 10, 16, 'نو بیا د څښتن اطاعت کوئ او نور سرزوري مه کوئ.', 'نو بیا د چشتن اطاعت کوی او نور سرزوری مه کوی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Deuteronomy_10_16.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237843, 1761237843),
(45546, 'Deuteronomy 10:17', 'Deuteronomy', 10, 17, 'ستاسو څښتن د څښتنانو څښتن او د خدایانو خدای دی. هغه لوی او قوي دی او د هغه څخه وېره په کار ده. هغه د چا طرفداري نه کوي او تل عادلانه پرېکړې کوي.', 'ستاسو چشتن د چشتنانو چشتن او د خدایانو خدای دی. هغه لوی او قوی دی او د هغه چخه وېره په کار ده. هغه د چا طرفداری نه کوی او تل عادلانه پرېکرې کوی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Deuteronomy_10_17.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237843, 1761237843),
(45547, 'Deuteronomy 10:18', 'Deuteronomy', 10, 18, 'څښتن د یتیمانو او کونډو د حقونو څخه دفاع کوي. هغه د هغو پردیو خلکو سره مینه کوي چې زمونږ د قوم سره اوسیږي او هغوی ته خواړه او کالي ورکوي.', 'چشتن د یتیمانو او کوندو د حقونو چخه دفاع کوی. هغه د هغو پردیو خلکو سره مینه کوی چې زمونز د قوم سره اوسیزی او هغوی ته خواره او کالی ورکوی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Deuteronomy_10_18.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237843, 1761237843),
(45548, 'Deuteronomy 10:19', 'Deuteronomy', 10, 19, 'نو بیا د هغو پردیو خلکو سره مینه کوئ، ځکه چې تاسو خپله یو وخت په مصر کې پردي وئ.', 'نو بیا د هغو پردیو خلکو سره مینه کوی، جکه چې تاسو خپله یو وخت په مصر کې پردی وی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Deuteronomy_10_19.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237843, 1761237843),
(45549, 'Deuteronomy 10:20', 'Deuteronomy', 10, 20, 'د خپل څښتن خدای څخه وېره کوئ او یوازې د هغه عبادت کوئ. هغه ته وفادار اوسئ او یوازې د هغه په نوم قسم خورئ.', 'د خپل چشتن خدای چخه وېره کوی او یوازې د هغه عبادت کوی. هغه ته وفادار اوسی او یوازې د هغه په نوم قسم خوری.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Deuteronomy_10_20.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237843, 1761237843),
(45550, 'Deuteronomy 10:21', 'Deuteronomy', 10, 21, 'د هغه ستاینه کوئ. هغه ستاسو خدای دی او تاسو هغه لوی لوی او عجیبه کارونه په خپلو سترګو ولیدل چې ستاسو دپاره یې کړي دي.', 'د هغه ستاینه کوی. هغه ستاسو خدای دی او تاسو هغه لوی لوی او عجیبه کارونه په خپلو سترګو ولیدل چې ستاسو دپاره یې کری دی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Deuteronomy_10_21.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237843, 1761237843),
(45551, 'Deuteronomy 10:22', 'Deuteronomy', 10, 22, 'کله چې ستاسو نیکونه مصر ته لاړل چې هلته واوسیږي، هغوی یوازې اویا تنه وو. خو اوس ستاسو څښتن خدای ستاسو شمېر د اسمان د ستورو په شان زیات کړی دی.', 'کله چې ستاسو نیکونه مصر ته لارل چې هلته واوسیزی، هغوی یوازې اویا تنه وو. خو اوس ستاسو چشتن خدای ستاسو شمېر د اسمان د ستورو په شان زیات کری دی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Deuteronomy_10_22.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237843, 1761237843),
(45552, 'Daniel 6:1', 'Daniel', 6, 1, 'داريوس دا فېصله وکړه چې ټوله بادشاهى په يو سل او شل صوبو باندې تقسيم کړى، او هغۀ لوئ آفسران مقرر کړل چې په هره صوبه حکمرانى وکړى.', 'داریوس دا فېصله وکره چې توله بادشاهی په یو سل او شل صوبو باندې تقسیم کری، او هغۀ لوی افسران مقرر کرل چې په هره صوبه حکمرانی وکری.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Daniel_6_1.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237843, 1761237843),
(45553, 'Daniel 6:2', 'Daniel', 6, 2, 'بادشاه دانيال او دوه نور کسان په دې آفسرانو سر پرست مقرر کړل چې په آفسرانو او د بادشاه په ګټو باندې نظر وساتى.', 'بادشاه دانیال او دوه نور کسان په دې افسرانو سر پرست مقرر کرل چې په افسرانو او د بادشاه په ګتو باندې نظر وساتی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Daniel_6_2.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237843, 1761237843),
(45554, 'Daniel 6:3', 'Daniel', 6, 3, 'دانيال زر دا ثابته کړه چې هغه د نورو وزيرانو او لوئ آفسرانو نه ډېر قابل دے. نو بيا ځکه بادشاه دا فېصله وکړه چې هغه په ټوله بادشاهۍ باندې حاکِم مقرر کړى.', 'دانیال زر دا ثابته کره چې هغه د نورو وزیرانو او لوی افسرانو نه دېر قابل دے. نو بیا جکه بادشاه دا فېصله وکره چې هغه په توله بادشاهی باندې حاکم مقرر کری.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Daniel_6_3.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237843, 1761237843),
(45555, 'Daniel 6:4', 'Daniel', 6, 4, 'نو په دې وجه نور وزيران او لوئ آفسران په دې لټون کښې شُو چې د هغۀ په حکومتى انتظام کښې څۀ داسې غلطى پېدا کړى. خو هغوئ څۀ داسې هيڅ څيز د هغۀ خلاف پېدا نۀ کړلو چې هغه پرې ملامته کړى، ځکه چې هغه ډېر ايماندار وو او هيڅ قسم غلطى او بې‌ايمانى يې نۀ کوله.', 'نو په دې وجه نور وزیران او لوی افسران په دې لتون کشې شو چې د هغۀ په حکومتی انتظام کشې چۀ داسې غلطی پېدا کری. خو هغوی چۀ داسې هیچ چیز د هغۀ خلاف پېدا نۀ کرلو چې هغه پرې ملامته کری، جکه چې هغه دېر ایماندار وو او هیچ قسم غلطی او بې‌ایمانی یې نۀ کوله.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Daniel_6_4.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237843, 1761237843),
(45556, 'Daniel 6:5', 'Daniel', 6, 5, 'آخر هغه کسانو دا ووئيل چې، ”دې طريقې سره به مونږ په دانيال هيڅ قِسمه اِلزام ونۀ لګولے شُو. خو يوه خبر ده چې د اِلزام باعث جوړېدے شى يعنې د هغۀ د خُدائ پاک د شريعت په حقله.“', 'اخر هغه کسانو دا ووییل چې، ”دې طریقې سره به مونز په دانیال هیچ قسمه الزام ونۀ لګولے شو. خو یوه خبر ده چې د الزام باعث جورېدے شی یعنې د هغۀ د خدای پاک د شریعت په حقله.“', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Daniel_6_5.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237843, 1761237843),
(45557, 'Daniel 6:6', 'Daniel', 6, 6, 'نو بيا وزيران او لوئ آفسران په يو ځائ بادشاه له ورغلل او ورته يې ووئيل چې، ”داريوس بادشاه دې د تل دپاره ژوندے وى.', 'نو بیا وزیران او لوی افسران په یو جای بادشاه له ورغلل او ورته یې ووییل چې، ”داریوس بادشاه دې د تل دپاره ژوندے وی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Daniel_6_6.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237843, 1761237843),
(45558, 'Daniel 6:7', 'Daniel', 6, 7, 'مونږ د ټول مُلک شاهى وزيران، آفسران، مشيران، مشران او حاکمان په دې راضى شوى يُو چې بادشاه دې يو فرمان جارى کړى او په سختۍ سره دې په هغې عمل وکړے شى چې په راتلونکو دېرشو ورځو کښې هر څوک چې هم ستا نه بغېر د بل معبود يا انسان عبادت وکړى، نو هغه دې د زمرو په غار کښې واچولے شى.', 'مونز د تول ملک شاهی وزیران، افسران، مشیران، مشران او حاکمان په دې راضی شوی یو چې بادشاه دې یو فرمان جاری کری او په سختی سره دې په هغې عمل وکرے شی چې په راتلونکو دېرشو ورجو کشې هر چوک چې هم ستا نه بغېر د بل معبود یا انسان عبادت وکری، نو هغه دې د زمرو په غار کشې واچولے شی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Daniel_6_7.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237843, 1761237843),
(45559, 'Daniel 6:8', 'Daniel', 6, 8, 'نو اوس، اے بادشاه سلامت، دا حکم جارى کړه او مهر پرې ولګوه چې څوک هم دا بدل نۀ کړے شى، لکه د ميديانو او فارسيانو د قانون په مطابق چې نۀ منسوخ کېدونکے دے.“', 'نو اوس، اے بادشاه سلامت، دا حکم جاری کره او مهر پرې ولګوه چې چوک هم دا بدل نۀ کرے شی، لکه د میدیانو او فارسیانو د قانون په مطابق چې نۀ منسوخ کېدونکے دے.“', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Daniel_6_8.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237843, 1761237843),
(45560, 'Daniel 6:9', 'Daniel', 6, 9, 'نو بيا داريوس بادشاه په ليکل شوے فرمان دستخط وکړو.', 'نو بیا داریوس بادشاه په لیکل شوے فرمان دستخط وکرو.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Daniel_6_9.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237843, 1761237843);